void *jas_realloc2(void *ptr, size_t num_elements, size_t element_size) /* <=== jas_realloc2 */ 
{
	size_t size;
	if (!jas_safe_size_mul(num_elements, element_size, &size)) {
		return 0;
	}
	return jas_realloc(ptr, size);
}

void *jas_realloc(void *ptr, size_t size) /* <=== jas_realloc */ 
{
	void *result;
	JAS_DBGLOG(101, ("jas_realloc called with %x,%zu\n", ptr, size));
	result = realloc(ptr, size);
	JAS_DBGLOG(100, ("jas_realloc(%p, %zu) -> %p\n", ptr, size, result));
	return result;
}

inline static bool jas_safe_size_mul(size_t x, size_t y, size_t *result) /* <=== jas_safe_size_mul */ 
{
	/* Check if overflow would occur */
	if (x && y > SIZE_MAX / x) {
		/* Overflow would occur. */
		*result = 0;
		return false;
	}
	*result = x * y;
	return true;
}

